\begin{lemma}
    \label{prob_ineq}
    If $\mathcal{U}$ and $\mathcal{V}$ are two events
    with $\mathrm{Pr}[\mathcal{V}] < 1$, then
    $$
        \mathrm{Pr}[\mathcal{U} \vee \mathcal{V}] \geq \mathrm{Pr}[\mathcal{U} \mid \neg \mathcal{V}].
    $$
\end{lemma}
\begin{proof}
    \begin{align*}
        \Prb{}{\Uc \vee \Vc} &= \Prb{}{\Vc} + \Prb{}{\Uc \mid \neg \Vc} \Prb{}{\neg \Vc}\\
        &\ge  \Prb{}{\Uc \mid \neg \Vc}  \Prb{}{\Vc} + \Prb{}{\Uc \mid \neg \Vc} \Prb{}{\neg \Vc}\\
        &=\Prb{}{\Uc \mid \neg \Vc}
    \end{align*}
\end{proof}

